sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Check if the date field 'fecha_licitacion' has a value
    if (!current.fecha_licitacion.nil()) {
        // 2. Initialize GlideDate with the field value
        var gDate = new GlideDate();
        gDate.setValue(current.getValue('fecha_licitacion'));

        // 3. Extract components
        var month = parseInt(gDate.getMonthNoTZ());
        var year = parseInt(gDate.getYearNoTZ());

        // 4. Calculate Quarter (1-4)
        var quarter = Math.ceil(month / 3);

        // 5. Update the target fields
        current.mes = month;
        current.trimestre = quarter;
        current.ano = year;
    } else {
        // Optional: Clear the fields if the date is removed
        current.mes = '';
        current.trimestre = '';
        current.ano = '';
    }

})(current, previous);
